import json
NEG = "text, letters, words, subtitles, captions, watermark, deformed hands, extra fingers, extra limbs, extra people, morphing face, face distortion, photorealistic, plastic toy look, blurry face"
S = "Painted 2D/3D animated feature film shot, same character design as the image (messy brown hair, thick eyebrows, long nose, light beard, plum jacket), expressive snappy cartoon acting with anticipation and follow-through."
TALK = " His mouth moves clearly as he talks."
PLANS = {
 "A": ("ref/fin-film-p5-hd.jpg", "cles/A_fin/sortie-1.jpg", 4, f"{S} Same room, same static camera. The cartoon rocket hovering under the ceiling sputters; he lowers his arms, glances up at it, then gives the camera an exaggerated grimace, reaches up and shoves the rocket sideways: it zips out of the frame to the right leaving a smoke trail. Arm still extended, he looks at the camera sarcastically and starts talking.{TALK}"),
 "B": ("cles/B/sortie-1.jpg", None, 3, f"{S} Close shot, static camera. He leans closer to the camera and whispers conspiratorially, eyebrows wiggling, sly grin; at the very end he snaps his fingers dramatically next to his face.{TALK}"),
 "C": ("cles/C_debut/sortie-1.jpg", "cles/C_fin/sortie-1.jpg", 3, f"{S} Right after the finger snap, the bedroom folds away like a theater set: the walls fold down into layered paper cut-out flats that turn into flying paper pages and illustrated paper scenery bathed in deep midnight-blue light; a big wave of blue light sweeps across; two big glowing paper shapes, a disc and a rounded square, swoosh toward him and he ducks just in time, covering his head, eyes wide."),
 "D": ("cles/D/sortie-1.jpg", None, 4, f"{S} Static camera. He types energetically on the floating keyboard of light while glancing and talking to the camera with a complicit smile, then throws his arms wide open and looks around in wonder as colored glass tiles and paper sheets swirl around him.{TALK}"),
 "F": ("cles/F_debut/sortie-1.jpg", "cles/F_fin/sortie-1.jpg", 4, f"{S} Static camera. He tries to grab the glowing firefly emblem: it slips out of his hands like a wet bar of soap and bounces in the air, he catches it again clumsily and slaps it onto the front of the packaging box where it becomes the printed logo; then he strikes a ridiculous triumphant pose with his fist raised high."),
 "G": ("cles/G_debut/sortie-1.jpg", "cles/G_fin/sortie-1.jpg", 3, f"{S} Static wide camera. He sets the lamp down on the ground; the ground trembles; a giant website architecture rises out of the ground around him: a huge billboard wall and tall product-card doors slot into place with puffs of dust, a giant green shopping cart rolls in; he stands up, amazed."),
 "H": ("cles/H/sortie-1.jpg", None, 3, f"{S} Tracking camera moving backward. He runs toward the camera pushing the giant green shopping cart through the alley of product-card doors, hair and jacket flying, euphoric, talking excitedly.{TALK}"),
 "I": ("cles/I/sortie-1.jpg", None, 4, f"{S} Static close shot. He raises the white mug to drink, tips it, peers inside: it is empty. His face collapses into exaggerated comic despair; he looks at the camera with huge sad eyes and talks.{TALK}"),
 "J": ("cles/J_debut/sortie-1.jpg", "cles/J_fin/sortie-1.jpg", 3, f"{S} He looks at the photo proudly, then flings it up into the sky; the photo unfolds and grows into a giant advertising banner filling the sky above him; the camera tilts up slightly as he turns and looks up in awe."),
 "K": ("cles/K_fix/sortie-1.jpg", None, 3, f"{S} Static camera inside a bright advertising world. On the big screen, his double waves cheerfully; he waves back, amazed and delighted, talking; the giant lamp floats and glows; round shapes drift slowly.{TALK}"),
 "L": ("cles/L_fix/sortie-1.jpg", None, 4, f"{S} Static camera. He runs fast on the giant moving conveyor-belt calendar while the square posts slide by on the rails above; then he suddenly stops, turns to the camera and presents everything around him with both arms, very proud, talking.{TALK}"),
 "M": ("cles/M_fix/sortie-1.jpg", None, 4, f"{S} Static camera. He looks at his shop thoughtfully, chin in hand, squints suspiciously, then slowly turns to the camera with a mischievous smile, raises one finger and talks.{TALK}"),
 "N": ("cles/N_fix/sortie-1.jpg", None, 3, f"{S} Static camera. He talks to the camera with a mischievous grin and types quickly on the floating keyboard of light.{TALK}"),
 "O": ("cles/M_fix/sortie-1.jpg", "cles/O_fin/sortie-1.jpg", 4, f"{S} Static wide camera. The shop transforms into a premium version: colors deepen to dark plum and gold, the layout reorganizes, elegant panels slide up into place. He suddenly ducks as something huge flies over his head; then a big glowing green pill-shaped button pops up from the floor right in front of him and bumps him backward; he stumbles, regains his balance and looks proudly at the camera."),
 "P": ("cles/P/sortie-1.jpg", None, 5, f"{S} Static camera. He looks around at the piles of tools on his left and right, then at his laptop, then stares at the camera in total disbelief and talks, gesturing at the tools with both hands.{TALK}"),
 "Q": ("cles/P/sortie-1.jpg", "cles/Q_fin/sortie-1.jpg", 4, f"{S} Static camera. He snaps his fingers: the piles of tools disappear one after another in little puffs of smoke; one last stubborn box stays and wobbles defiantly; he gives it a little kick and it vanishes in a puff; he shrugs nonchalantly at the camera."),
 "R": ("cles/R/sortie-1.jpg", None, 3, f"{S} Static close-up. He leans a little closer to the camera with a warm smile, winks, and talks.{TALK}"),
 "S": ("cles/S/sortie-1.jpg", None, 4, f"{S} Static camera on a deep midnight-blue stage. He gestures invitingly to the camera and talks, then leans his elbow on the pedestal; his elbow slips off, he almost falls, flails and catches himself at the very last moment with an embarrassed grin.{TALK}"),
}
for k, (start, end, dur, prompt) in PLANS.items():
    b = {"prompt": prompt, "start_image_url": "@fichier:" + start, "duration": str(dur), "aspect_ratio": "9:16", "generate_audio": False, "negative_prompt": NEG}
    if end: b["end_image_url"] = "@fichier:" + end
    json.dump(b, open(f"anim/req-{k}.json", "w"), ensure_ascii=False)
print(len(PLANS), "plans,", sum(v[2] for v in PLANS.values()), "s")
